class MagicDictionary:
    def __init__(self):
        self.buckets = {}

    def buildDict(self, dictionary):
        for w in dictionary:
            self.buckets.setdefault(len(w), []).append(w)

    def search(self, searchWord):
        for w in self.buckets.get(len(searchWord), []):
            diff = sum(a != b for a, b in zip(w, searchWord))
            if diff == 1:
                return True
        return False

