class MagicDictionary {
    private Map<Integer, List<String>> buckets = new HashMap<>();

    public MagicDictionary() {}

    public void buildDict(String[] dictionary) {
        for (String w : dictionary)
            buckets.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
    }

    public boolean search(String searchWord) {
        int n = searchWord.length();
        for (String w : buckets.getOrDefault(n, new ArrayList<>())) {
            int diff = 0;
            for (int i = 0; i < n && diff <= 1; i++)
                if (w.charAt(i) != searchWord.charAt(i)) diff++;
            if (diff == 1) return true;
        }
        return false;
    }
}

