        neighbors.clear();
        string letters = "abcdefghijklmnopqrstuvwxyz";
        for (auto& w : dictionary)
            for (int i = 0; i < (int)w.size(); i++) {
                char orig = w[i];
                for (char c : letters)
                    if (c != orig) { w[i] = c; neighbors.insert(w); }
                w[i] = orig;
            }
    }

    bool search(string searchWord) {
        string letters = "abcdefghijklmnopqrstuvwxyz";
        for (int i = 0; i < (int)searchWord.size(); i++) {
            char orig = searchWord[i];
            for (char c : letters)
                if (c != orig) {
                    searchWord[i] = c;
                    if (neighbors.count(searchWord)) return true;
                }
            searchWord[i] = orig;
        }
