class MagicDictionary {
    private Set<String> neighbors = new HashSet<>();

    public MagicDictionary() {}

    public void buildDict(String[] dictionary) {
        neighbors.clear();
        for (String w : dictionary) {
            char[] arr = w.toCharArray();
            for (int i = 0; i < arr.length; i++) {
                char orig = arr[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    if (c == orig) continue;
                    arr[i] = c;
                    neighbors.add(new String(arr));
                }
                arr[i] = orig;
            }
        }
    }

    public boolean search(String searchWord) {
        char[] arr = searchWord.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            char orig = arr[i];
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == orig) continue;
                arr[i] = c;
                if (neighbors.contains(new String(arr))) return true;
            }
            arr[i] = orig;
        }
        return false;
    }
}

